def filled_diamond(radius):
    """Filled diamond (rhombus) pattern with given cell radius"""
    result = []
    for r in range(-radius * 2, radius * 2):
        row = []
        # For vertical offset r, width is determined by diamond equation
        # |r| + |c-offset| <= radius offset here is 0 for center
        # Simple approach: enumerate based on triangle
        for c in range(-radius, radius + 1):
            result.append(1 if abs(r) + abs(c - radius) < radius + 1 and -radius*2 <= c+radius*2 <= radius*2 else 0)
    return result

